import{_ as o,c as l,a2 as i,o as p}from"./chunks/framework.CqbvlPrP.js";const d=JSON.parse('{"title":"第一千二百章零一章 放逸等品 增支部1集81经到97经","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/1201第一千二百章零一章 放逸等品 增支部1集81经到97经.md","filePath":"meditation/巴利文大藏经/1201第一千二百章零一章 放逸等品 增支部1集81经到97经.md"}'),a={name:"meditation/巴利文大藏经/1201第一千二百章零一章 放逸等品 增支部1集81经到97经.md"};function r(u,t,e,q,s,_){return p(),l("div",null,t[0]||(t[0]=[i('<h1 id="第一千二百章零一章-放逸等品-增支部1集81经到97经" tabindex="-1">第一千二百章零一章 放逸等品 增支部1集81经到97经 <a class="header-anchor" href="#第一千二百章零一章-放逸等品-增支部1集81经到97经" aria-label="Permalink to &quot;第一千二百章零一章 放逸等品 增支部1集81经到97经&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>增支部1集81经到97经</p><p>放逸等品</p><p>81经</p><ol start="81"><li>&quot;比丘们,这种增长是微不足道的,也就是名声的增长。比丘们,增长中最殊胜的是智慧的增长。因此,比丘们,你们应当如此学习:&#39;我们将在智慧的增长上增长。&#39;比丘们,你们应当如此学习。&quot;第一经。</li></ol><p>82经</p><ol start="82"><li>&quot;比丘们,我不见有任何一法,能如此导致大的不利,如这放逸。比丘们,放逸导致大的不利。&quot;第二经。</li></ol><p>83经</p><ol start="83"><li>&quot;比丘们,我不见有任何一法,能如此导致大的利益,如这不放逸。比丘们,不放逸导致大的利益。&quot;第三经。</li></ol><p>84经</p><ol start="84"><li>&quot;比丘们,我不见有任何一法,能如此导致大的不利,如这懈怠。比丘们,懈怠导致大的不利。&quot;第四经。</li></ol><p>85经</p><ol start="85"><li>&quot;比丘们,我不见有任何一法,能如此导致大的利益,如这精进。比丘们,精进导致大的利益。&quot;第五经。</li></ol><p>86经</p><ol start="86"><li>&quot;比丘们,我不见有任何一法,能如此导致大的不利,如这多欲。比丘们,多欲导致大的不利。&quot;第六经。</li></ol><p>87经</p><ol start="87"><li>&quot;比丘们,我不见有任何一法,能如此导致大的利益,如这少欲。比丘们,少欲导致大的利益。&quot;第七经。</li></ol><p>88经</p><ol start="88"><li>&quot;比丘们,我不见有任何一法,能如此导致大的不利,如这不知足。比丘们,不知足导致大的不利。&quot;第八经。</li></ol><p>89经</p><ol start="89"><li>&quot;比丘们,我不见有任何一法,能如此导致大的利益,如这知足。比丘们,知足导致大的利益。&quot;第九经。</li></ol><p>90经</p><ol start="90"><li>&quot;比丘们,我不见有任何一法,能如此导致大的不利,如这不如理作意。比丘们,不如理作意导致大的不利。&quot;第十经。</li></ol><p>91经</p><ol start="91"><li>&quot;比丘们,我不见有任何一法,能如此导致大的利益,如这如理作意。比丘们,如理作意导致大的利益。&quot;第十一经。</li></ol><p>92经</p><ol start="92"><li>&quot;比丘们,我不见有任何一法,能如此导致大的不利,如这不正知。比丘们,不正知导致大的不利。&quot;第十二经。</li></ol><p>93经</p><ol start="93"><li>&quot;比丘们,我不见有任何一法,能如此导致大的利益,如这正知。比丘们,正知导致大的利益。&quot;第十三经。</li></ol><p>94经</p><ol start="94"><li>&quot;比丘们,我不见有任何一法,能如此导致大的不利,如这恶友。比丘们,恶友导致大的不利。&quot;第十四经。</li></ol><p>95经</p><ol start="95"><li>&quot;比丘们,我不见有任何一法,能如此导致大的利益,如这善友。比丘们,善友导致大的利益。&quot;第十五经。</li></ol><p>96经</p><ol start="96"><li>&quot;比丘们,我不见有任何一法,能如此导致大的不利,如这修习不善法、不修习善法。比丘们,修习不善法、不修习善法导致大的不利。&quot;第十六经。</li></ol><p>97经</p><ol start="97"><li>&quot;比丘们,我不见有任何一法,能如此导致大的利益,如这修习善法、不修习不善法。比丘们,修习善法、不修习不善法导致大的利益。&quot;第十七经。</li></ol><p>放逸等品第九终。</p>',39)]))}const c=o(a,[["render",r]]);export{d as __pageData,c as default};
